#include "actuatorSafetyGate_behavior.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void actuatorSafetyGate_behavior_initialize(void);
void actuatorSafetyGate_behavior_notify(microkit_channel channel);
void actuatorSafetyGate_behavior_timeTriggered(void);

volatile sb_queue_bool_1_t *actuationAuthority_queue_1;
sb_queue_bool_1_Recv_t actuationAuthority_recv_queue;
volatile sb_queue_FlightStack_ProposedActuatorRates_1_t *proposedRates_queue_1;
sb_queue_FlightStack_ProposedActuatorRates_1_Recv_t proposedRates_recv_queue;
volatile sb_queue_FlightStack_ActuatorCommand_1_t *actuatorCommand_queue_1;

#define PORT_FROM_MON 46

bool last_actuationAuthority_payload;

bool get_actuationAuthority(bool *data) {
  sb_event_counter_t numDropped;
  bool fresh_data;
  bool isFresh = sb_queue_bool_1_dequeue((sb_queue_bool_1_Recv_t *) &actuationAuthority_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_actuationAuthority_payload = fresh_data;
  }
  *data = last_actuationAuthority_payload;
  return isFresh;
}

FlightStack_ProposedActuatorRates last_proposedRates_payload;

bool get_proposedRates(FlightStack_ProposedActuatorRates *data) {
  sb_event_counter_t numDropped;
  FlightStack_ProposedActuatorRates fresh_data;
  bool isFresh = sb_queue_FlightStack_ProposedActuatorRates_1_dequeue((sb_queue_FlightStack_ProposedActuatorRates_1_Recv_t *) &proposedRates_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_proposedRates_payload = fresh_data;
  }
  *data = last_proposedRates_payload;
  return isFresh;
}

bool put_actuatorCommand(const FlightStack_ActuatorCommand *data) {
  sb_queue_FlightStack_ActuatorCommand_1_enqueue((sb_queue_FlightStack_ActuatorCommand_1_t *) actuatorCommand_queue_1, (FlightStack_ActuatorCommand *) data);

  return true;
}

void init(void) {
  sb_queue_bool_1_Recv_init(&actuationAuthority_recv_queue, (sb_queue_bool_1_t *) actuationAuthority_queue_1);

  sb_queue_FlightStack_ProposedActuatorRates_1_Recv_init(&proposedRates_recv_queue, (sb_queue_FlightStack_ProposedActuatorRates_1_t *) proposedRates_queue_1);

  sb_queue_FlightStack_ActuatorCommand_1_init((sb_queue_FlightStack_ActuatorCommand_1_t *) actuatorCommand_queue_1);

  actuatorSafetyGate_behavior_initialize();
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      actuatorSafetyGate_behavior_timeTriggered();
      break;
    default:
      actuatorSafetyGate_behavior_notify(channel);
  }
}
